// ── RANDOM MODE — fictional cities, teams, and player names ───────────
const RANDOM_CITIES = ['Austin','Louisville','Pittsburgh','Las Vegas','St. Louis','Kansas City','Seattle','Nashville','Vancouver','Baltimore','Raleigh','Hartford','Tulsa','Spokane','Baton Rouge','Albuquerque','Tucson','Richmond','Omaha','Tampa'];
const RANDOM_NICKS  = ['Thunder','Blaze','Surge','Lions','Hawks','Storm','Wolves','Fury','Force','Legends','Knights','Fire','Sky','Aces','Vipers','Phantoms','Monarchs','Titans','Comets','Pioneers'];
const RANDOM_FIRST  = ['Marcus','Jordan','Devon','Tyrell','Isaiah','Damon','Kendall','Avery','Malik','Corey','Antoine','Darius','Caleb','Treyvon','Elijah','Nathan','Jaxon','Bryson','Cameron','Quincy','Ahmad','Lorenzo','Stephan','Darrius','Vincent','Tobias','Xavier','Rasheed','Calvin','Demarcus'];
const RANDOM_LAST   = ['Ellis','Hayes','Carter','Washington','Brooks','Pierce','West','Stone','Okafor','Langston','Bell','Simmons','Morgan','Parker','Cross','Rivera','Cole','Tanner','Miles','Foster','Bailey','Banks','Grant','Hill','Webb','Marsh','Quinn','Turner','Winters','Floyd'];
function makeRandomLeague(seed=42) {
  // Seeded shuffle so it's stable per session
  const rng = (n) => { seed = (seed*1664525+1013904223)&0xffffffff; return Math.abs(seed)%n; };
  const cities = [...RANDOM_CITIES].sort(()=>rng(3)-1).slice(0,30);
  const nicks  = [...RANDOM_NICKS, ...RANDOM_NICKS].sort(()=>rng(3)-1).slice(0,30);
  const teamMap = {}; // teamId → {city, name, clr}
  const TEAM_IDS = ['ATL','BOS','BKN','CHA','CHI','CLE','DAL','DEN','DET','GSW','HOU','IND','LAC','LAL','MEM','MIA','MIL','MIN','NOP','NYK','OKC','ORL','PHI','PHX','POR','SAC','SAS','TOR','UTA','WAS'];
  const CLRS = ['#E03A3E','#007A33','#000000','#1D1160','#CE1141','#860038','#007AC1','#FEC524','#C8102E','#1D428A','#CE1141','#002D62','#C8102E','#552583','#5D76A9','#98002E','#00471B','#005083','#0C2340','#006BB6','#007AC1','#0077C0','#006BB6','#E56020','#E03A3E','#5A2D81','#C4CED4','#CE1141','#002B5C','#E31837'];
  TEAM_IDS.forEach((id,i)=>{ teamMap[id]={city:cities[i],name:nicks[i],clr:CLRS[i]}; });
  return teamMap;
}
function randomPlayerName(i=0) {
  return `${RANDOM_FIRST[i%RANDOM_FIRST.length]} ${RANDOM_LAST[(i+7)%RANDOM_LAST.length]}`;
}

