// Real roster loader — uses NBA_ROSTERS for top players, procedural bench for rest
// Era-aware roster builder — ERA_ROSTERS is the single source of truth for
// every era (historical, 2024, and 2025), falling back to generated
// era-appropriate players only where specific research hasn't been done.
// Historical era first/last names by decade
const ERA_NAMES = {
  '40s': { fn:['George','Bob','Jim','Ed','Bill','Joe','Frank','Max','Al','Carl','Harry','Mel','Arnie','Herm','Slater','Johnny','Don','Red','Buddy','Walt'], ln:['Mikan','Davies','Pollard','Sadowski','Feerick','Fulks','Zaslofsky','Cervi','Groza','Beard','Braun','Gallatin','Risen','Wanzer','Martin','Logan','Senesky','Jeannette','McKinney','Halbert'] },
  '50s': { fn:['Bob','Bill','Paul','Neil','Dolph','Clyde','Tom','Dick','Frank','Jack','Gene','Chuck','Larry','Andy','Slater','Bob','Vern','Harry','Jim','Carl'], ln:['Cousy','Sharman','Arizin','Johnston','Schayes','Lovellette','Heinsohn','Ricketts','Ramsey','Twyman','Shue','Noble','Foust','Phillip','Martin','Davies','Mikkelsen','Gallatin','Pollard','Braun'] },
  '60s': { fn:['Jerry','Elgin','Oscar','Wilt','Sam','John','KC','Hal','Chet','Gus','Dave','Bailey','Don','Len','Willis','Walt','Bill','Luke','Wali','Nate'], ln:['West','Baylor','Robertson','Chamberlain','Jones','Havlicek','Jones','Greer','Walker','Rodgers','Bing','Howell','Nelson','Chappell','Reed','Frazier','Bradley','Jackson','Jones','Thurmond'] },
  '70s': { fn:['Julius','Dave','Kareem','Pete','Bob','Elvin','Wes','Rick','Nate','Jo Jo','Paul','Charlie','Alvan','Phil','Jamaal','Dennis','Gus','Jack','Artis','Bob'], ln:['Erving','Cowens','Abdul-Jabbar','Maravich','McAdoo','Hayes','Unseld','Barry','Archibald','White','Westphal','Scott','Adams','Smith','Wilkes','Johnson','Williams','Sikma','Gilmore','Dandridge'] },
  '80s': { fn:['Magic','Larry','Moses','Charles','Michael','Scottie','Dominique','Clyde','Patrick','Karl','John','James','Robert','Kevin','Alex','Dennis','Mark','Terry','Dale','Buck'], ln:['Johnson','Bird','Malone','Barkley','Jordan','Pippen','Wilkins','Drexler','Ewing','Malone','Stockton','Worthy','Parish','McHale','English','Rodman','Aguirre','Cummings','Ellis','Williams'] },
  '90s': { fn:['Reggie','Gary','Shawn','David','Tim','Hakeem','Grant','Penny','Jason','Vin','Latrell','Allan','Derek','Antonio','Tom','Mitch','Terry','Rik','Chris','Detlef'], ln:['Miller','Payton','Kemp','Robinson','Duncan','Olajuwon','Hill','Hardaway','Kidd','Baker','Sprewell','Houston','Fisher','Davis','Gugliotta','Richmond','Porter','Smits','Webber','Schrempf'] },
  '00s': { fn:['Kobe','LeBron','Tracy','Kevin','Dwyane','Paul','Amare','Carmelo','Tony','Manu','Steve','Dirk','Ray','Paul','Vince','Richard','Ben','Chauncey','Joe','Jason'], ln:['Bryant','James','McGrady','Garnett','Wade','Pierce','Stoudemire','Anthony','Parker','Ginobili','Nash','Nowitzki','Allen','Gasol','Carter','Hamilton','Wallace','Billups','Dumars','Kidd'] },
};

function eraNamePool(yr) {
  const y = parseInt(yr);
  if (y < 1950) return ERA_NAMES['40s'];
  if (y < 1960) return ERA_NAMES['50s'];
  if (y < 1970) return ERA_NAMES['60s'];
  if (y < 1980) return ERA_NAMES['70s'];
  if (y < 1990) return ERA_NAMES['80s'];
  if (y < 2000) return ERA_NAMES['90s'];
  if (y < 2010) return ERA_NAMES['00s'];
  return null; // use modern names for 2010+
}

function mkHistoricalPlayer(pos, targetOvr, eraId) {
  const pool = eraNamePool(eraId);
  const name = pool
    ? uniqueName(pool.fn, pool.ln)
    : uniqueName(FN, LN);
  return mkPlayerOvrNamed(pos, clamp(targetOvr, 48, 82), name);
}

function mkRosterReal(team, eraId='2024') {
  let realPlayers = [];
  const isHistorical = eraId !== '2024' && eraId !== '2025';
  const isCurrent    = eraId === '2024' || eraId === '2025';

  // Era-specific roster (historical, 2024, or 2025) - this is the single
  // source of truth for every era including 2024, which previously could be
  // silently overridden by a live fetch from an external, unverified
  // third-party GitHub repo whenever that fetch succeeded (it always did) -
  // meaning the accolades-aware salary system built for this era never
  // actually took effect in practice. Removed that fetch entirely so 2024
  // behaves the same verified way every other era already does.
  if (ERA_ROSTERS[eraId]?.[team.id]?.length) {
    const data = ERA_ROSTERS[eraId][team.id];
    realPlayers = data.map(([name,pos,age,a,salary,years,pot]) => {
      const attrs = {scoring:a[0],passing:a[1],rebounding:a[2],defense:a[3],athleticism:a[4],iq:a[5]};
      return {
        id: Math.random().toString(36).slice(2),
        name, pos, pos2: inferSecondaryPosition(pos, attrs), age,
        overall: calcOvr(attrs),
        potential: pot || 80,
        attrs,
        contract: { salary: Math.max(salary||4, getMinSalary()), years: years||2 },
        satisfaction: ri(55,85),
      };
    });
  }
  // Priority 3: 2024-25 NBA hardcoded rosters (fallback for 2024 era if no BBGM)
  else if (isCurrent && NBA_ROSTERS[team.id]?.length) {
    const data = NBA_ROSTERS[team.id];
    realPlayers = data.map(([name,pos,age,a,salary,years,pot]) => ({
      id: Math.random().toString(36).slice(2),
      name, pos,
      pos2: SEC_POS[pos]?.length && Math.random()<0.3 ? pick(SEC_POS[pos]) : null,
      age, overall: calcOvr({scoring:a[0],passing:a[1],rebounding:a[2],defense:a[3],athleticism:a[4],iq:a[5]}),
      potential: pot,
      attrs: {scoring:a[0],passing:a[1],rebounding:a[2],defense:a[3],athleticism:a[4],iq:a[5]},
      contract: {salary: Math.max(salary, getMinSalary()), years},
      satisfaction: ri(58,88),
    }));
  }
  // Priority 4: historical era with no specific data — generate era-appropriate players
  else if (isHistorical) {
    const baseOvr = (ERA_RTG_OVERRIDES[eraId]?.[team.id] || team.rtg) - 10;
    const starters = ['PG','SG','SF','PF','C'].map(pos =>
      mkHistoricalPlayer(pos, baseOvr + ri(2, 12), eraId)
    );
    const bench = Array.from({length:7}, () =>
      mkHistoricalPlayer(pick(['PG','SG','SF','PF','C']), baseOvr + ri(-8, 5), eraId)
    );
    realPlayers = [...starters, ...bench];
  }

  // NOTE: historical eras (era-specific ERA_ROSTERS) are NOT auto-filled with
  // generated bench players. Rosters reflect only real, researched players.
  // A team may show fewer than 12 if its bench hasn't been fully researched yet
  // — that's intentional (visible gap) rather than papering over it with fictional names.
  if (isCurrent) {
    const need = Math.max(0, 12 - realPlayers.length);
    const bench = Array.from({length:need}, () => mkPlayerOvr(
      pick(['PG','SG','SF','PF','C']),
      clamp(ri(team.rtg-26, team.rtg-10), 48, 76)
    ));
    realPlayers = [...realPlayers, ...bench];
  }

  return realPlayers;
}

function mkRoster(team) {
  return mkRosterReal(team);
}

