// ===================== UTILS =====================

const ri  = (a,b) => Math.floor(Math.random()*(b-a+1))+a;
const rf  = (a,b) => Math.random()*(b-a)+a;
const pick = arr => arr[Math.floor(Math.random()*arr.length)];
const clamp = (v,a,b) => Math.max(a,Math.min(b,v));
// Tracks every procedurally-generated fictional player name issued so far,
// so two different randomly-generated players (draft prospects, historical
// era fillers, retirement replacements) never collide on name. Previously
// name generation drew independently from a small ~50x90 combo pool every
// time with no uniqueness check at all — a single 60-player fictional draft
// class had roughly a 1-in-3 chance (birthday-paradox math) of drawing the
// same name twice, and it was reproduced live (two "Jaylen Williams" in one
// class). Shared by rname() and mkHistoricalPlayer()'s era-specific pools.
const _usedFictionalNames = new Set();
const uniqueName = (fnPool, lnPool) => {
  let n = `${pick(fnPool)} ${pick(lnPool)}`;
  let tries = 0;
  while (_usedFictionalNames.has(n) && tries < 50) {
    n = `${pick(fnPool)} ${pick(lnPool)}`;
    tries++;
  }
  _usedFictionalNames.add(n);
  return n;
};
const rname = () => uniqueName(FN, LN);
const fmt  = (n,d=1) => Number(n.toFixed(d));

function calcOvr(a) {
  // Rewards genuine specialization/dominance rather than a flat average,
  // which previously compressed the entire rating scale (even the most
  // statistically dominant real NBA seasons ever played - peak Jordan,
  // peak Curry, prime Wilt - topped out in the high-70s/low-80s). Matches
  // the same formula used to (re)calibrate every real historical player.
  const attrs = [a.scoring, a.passing, a.rebounding, a.defense, a.athleticism, a.iq];
  const weighted = a.scoring*0.30 + a.passing*0.20 + a.rebounding*0.12 + a.defense*0.20 + a.athleticism*0.08 + a.iq*0.10;
  const top2Avg = [...attrs].sort((x,y)=>y-x).slice(0,2).reduce((s,v)=>s+v,0) / 2;
  return Math.round(0.45*weighted + 0.55*top2Avg);
}

