function genRealDraftClass(eraId) {
  const real = REAL_DRAFT_CLASSES[eraId];
  if (!real) return null;
  return real.map(([name,pos,age,school,ovr],i) => {
    const p = mkPlayerOvr(pos, clamp(ovr-14,50,74), true);
    p.name = name; p.age = age; p.school = school;
    p.potential = clamp(ovr, 60, 99);
    p.mockSlot = i+1;
    p.scoutGrade = i<5?'Lottery Lock':i<14?'First Round Talent':i<30?'Second Round Upside':'Project';
    p.physTier = i<5?'Elite':i<14?'High':'Average';
    p.origin = school.match(/Ratiopharm|Real Madrid|Qingdao|Cedevita|Saint-Quentin/) ? 'International' : 'NCAA';
    return p;
  });
}

function genDraftClass() {
  const prospects = [];

  // Tier 1: Picks 1-5  — Lottery Locks (raw but elite ceiling)
  for (let i=0; i<5; i++) {
    const pos = pick(POSITIONS);
    const p   = mkPlayerOvr(pos, ri(64,74), true);
    p.potential = ri(78,88); p.scoutGrade = 'Lottery Lock';
    p.physTier = 'Elite'; p.origin = pick(DRAFT_ORIGINS); p.mockSlot = i+1;
    prospects.push(p);
  }
  // Tier 2: Picks 6-14 — First Round Talent
  for (let i=0; i<9; i++) {
    const pos = pick(POSITIONS);
    const p   = mkPlayerOvr(pos, ri(60,70), true);
    p.potential = ri(72,82); p.scoutGrade = 'First Round Talent';
    p.physTier = pick(['Elite','High']); p.origin = pick(DRAFT_ORIGINS); p.mockSlot = i+6;
    prospects.push(p);
  }
  // Tier 3: Picks 15-22 — Upside/Safe mix
  for (let i=0; i<8; i++) {
    const pos = pick(POSITIONS);
    const p   = mkPlayerOvr(pos, ri(57,66), true);
    p.potential = ri(68,78); p.scoutGrade = Math.random()<0.55?'Second Round Upside':'Safe Pick';
    p.physTier = pick(['High','Average']); p.origin = pick(DRAFT_ORIGINS); p.mockSlot = i+15;
    prospects.push(p);
  }
  // Tier 4: Picks 23-30 — Late first round
  for (let i=0; i<8; i++) {
    const pos = pick(POSITIONS);
    const p   = mkPlayerOvr(pos, ri(54,63), true);
    p.potential = ri(64,74);
    p.scoutGrade = Math.random()<0.35?'Project':Math.random()<0.5?'Safe Pick':'Second Round Upside';
    p.physTier = pick(['High','Average','Average']); p.origin = pick(DRAFT_ORIGINS); p.mockSlot = i+23;
    prospects.push(p);
  }
  // Tier 5: Picks 31-45 — Second round high
  for (let i=0; i<15; i++) {
    const pos = pick(POSITIONS);
    const p   = mkPlayerOvr(pos, ri(51,61), true);
    p.potential = ri(60,70);
    p.scoutGrade = Math.random()<0.5?'Project':Math.random()<0.5?'Second Round Upside':'Safe Pick';
    p.physTier = pick(['Average','High','Below']); p.origin = pick(DRAFT_ORIGINS); p.mockSlot = i+31;
    prospects.push(p);
  }
  // Tier 6: Picks 46-60 — Late second round
  for (let i=0; i<15; i++) {
    const pos = pick(POSITIONS);
    const p   = mkPlayerOvr(pos, ri(48,58), true);
    p.potential = ri(55,66);
    p.scoutGrade = Math.random()<0.65?'Project':'Safe Pick';
    p.physTier = pick(['Average','Below','Below']); p.origin = pick(DRAFT_ORIGINS); p.mockSlot = i+46;
    prospects.push(p);
  }

  return prospects.sort((a,b) => a.mockSlot - b.mockSlot);
}

function computeDraftOrder(teams) {
  const { order } = runDraftLottery(teams, selectedEra);
  return order;
}

// Same lottery logic as before, but also returns reveal-friendly data:
// which teams were in the pool, their pre-lottery seed (worst = #1),
// and where they actually landed — for the visible lottery screen.
// ── REAL DRAFT-NIGHT TEAM ASSIGNMENTS ── verified top picks for years where
// we already have a real draft class (REAL_DRAFT_CLASSES). Covers each year's
// most notable, well-documented picks — not the full round for every year,
// since draft-night trades multiply fast the deeper you go. Unlisted years/
// picks fall back to the normal simulated lottery below.
// Real historical head coaches, sourced from Basketball-Reference's yearly
// coaches pages (one team-season per key). Verified, complete coverage for
// these 3 eras only - sourcing all 30 teams across every one of the 80
// playable eras isn't feasible, so this covers the most commonly-picked
// featured eras first and falls back to a generated name elsewhere (see
// getRealCoach below), rather than claiming coverage that doesn't exist.
const REAL_COACHES = {
  '1995': {ATL:'Lenny Wilkens',BOS:'M.L. Carr',NOP:'Allan Bristow',CHI:'Phil Jackson',CLE:'Mike Fratello',DAL:'Dick Motta',DEN:'Bernie Bickerstaff',DET:'Doug Collins',GSW:'Rick Adelman',HOU:'Rudy Tomjanovich',IND:'Larry Brown',LAC:'Bill Fitch',LAL:'Del Harris',MIA:'Pat Riley',MIL:'Mike Dunleavy',MIN:'Flip Saunders',BKN:'Butch Beard',NYK:'Don Nelson',ORL:'Brian Hill',PHI:'John Lucas',PHX:'Cotton Fitzsimmons',POR:'P.J. Carlesimo',SAC:'Garry St. Jean',SAS:'Bob Hill',OKC:'George Karl',TOR:'Brendan Malone',UTA:'Jerry Sloan',MEM:'Brian Winters',WAS:'Jim Lynam'},
  '2024': {ATL:'Quin Snyder',BOS:'Joe Mazzulla',BKN:'Jordi Fernandez',CHI:'Billy Donovan',CHA:'Charles Lee',CLE:'Kenny Atkinson',DAL:'Jason Kidd',DEN:'Michael Malone',DET:'J.B. Bickerstaff',GSW:'Steve Kerr',HOU:'Ime Udoka',IND:'Rick Carlisle',LAC:'Tyronn Lue',LAL:'JJ Redick',MEM:'Taylor Jenkins',MIA:'Erik Spoelstra',MIL:'Doc Rivers',MIN:'Chris Finch',NOP:'Willie Green',NYK:'Tom Thibodeau',OKC:'Mark Daigneault',ORL:'Jamahl Mosley',PHI:'Nick Nurse',PHX:'Mike Budenholzer',POR:'Chauncey Billups',SAC:'Mike Brown',SAS:'Gregg Popovich',TOR:'Darko Rajakovic',UTA:'Will Hardy',WAS:'Brian Keefe'},
  '2025': {ATL:'Quin Snyder',BOS:'Joe Mazzulla',BKN:'Jordi Fernandez',CHI:'Billy Donovan',CHA:'Charles Lee',CLE:'Kenny Atkinson',DAL:'Jason Kidd',DEN:'David Adelman',DET:'J.B. Bickerstaff',GSW:'Steve Kerr',HOU:'Ime Udoka',IND:'Rick Carlisle',LAC:'Tyronn Lue',LAL:'JJ Redick',MEM:'Tuomas Iisalo',MIA:'Erik Spoelstra',MIL:'Doc Rivers',MIN:'Chris Finch',NOP:'Willie Green',NYK:'Mike Brown',OKC:'Mark Daigneault',ORL:'Jamahl Mosley',PHI:'Nick Nurse',PHX:'Jordan Ott',POR:'Tiago Splitter',SAC:'Doug Christie',SAS:'Mitch Johnson',TOR:'Darko Rajakovic',UTA:'Will Hardy',WAS:'Brian Keefe'},
};
// Falls back to a generated, clearly-fictional name so the game never shows
// a wrong real name - only a right one or an honest placeholder.
function getRealCoach(era, teamId, fallbackFn) {
  const real = REAL_COACHES[era]?.[teamId];
  if (real) return {name: real, isReal: true};
  return {name: fallbackFn(), isReal: false};
}

// Real teammates instead of generic fictional names - pulls actual players
// from the team's real roster for the mentor/rival/ally roles, keeping the
// archetype's flavor line (which is generic enough to fit any real player)
// while using their real name/position/age.
function selectRealTeammates(roster, myPos, myAge) {
  const pool = [...(roster||[])];
  const vets = pool.filter(p=>p.age>=30).sort((a,b)=>b.overall-a.overall);
  const mentorP = vets[0] || [...pool].sort((a,b)=>b.overall-a.overall)[0];
  const used = new Set(mentorP ? [mentorP.name] : []);
  const posMatches = pool.filter(p=>p.pos===myPos && !used.has(p.name)).sort((a,b)=>b.overall-a.overall);
  const rivalP = posMatches[0] || pool.filter(p=>!used.has(p.name)).sort((a,b)=>b.overall-a.overall)[0];
  if (rivalP) used.add(rivalP.name);
  const allyP = pool.filter(p=>!used.has(p.name)).sort((a,b)=>Math.abs(a.age-myAge)-Math.abs(b.age-myAge))[0];

  const mA = pick(MENTOR_TYPES), rA = pick(RIVAL_TYPES), aA = pick(ALLY_TYPES);
  return {
    mentor: mentorP ? {name:mentorP.name, pos:mentorP.pos, age:mentorP.age, archetype:mA.archetype, line:mA.line, isReal:true} : {...mA, isReal:false},
    rival:  rivalP  ? {name:rivalP.name,  pos:rivalP.pos,  age:rivalP.age,  archetype:rA.archetype, line:rA.line, isReal:true} : {...rA, isReal:false},
    ally:   allyP   ? {name:allyP.name,   pos:allyP.pos,   age:allyP.age,   archetype:aA.archetype, line:aA.line, isReal:true} : {...aA, isReal:false},
  };
}

const REAL_DRAFT_TEAMS = {
  '2024': ['ATL','WAS','HOU','SAS','DET','CHA','POR','SAS','MEM','UTA','CHI','OKC','SAC','POR','MIA','PHI','LAL','ORL','TOR','CLE','NOP','PHX','MIL','NYK','NYK','WAS','MIN','DEN','UTA','BOS'],
  '2025': ['DAL','SAS','PHI','CHA','UTA'],
  '2015': ['MIN','LAL','PHI','NYK','ORL','SAC','DEN','DET','CHA','MIA','IND','UTA','PHX','OKC','ATL','BOS','MIL','HOU','WAS','TOR'],
  '2003': ['CLE','DET','DEN','TOR','MIA','LAC','CHI','MIL','NYK','WAS','GDN','OKC','MEM','OKC','ORL','BOS','PHX','NOP','UTA','BOS'],
  '1999': ['CHI','OKC','CHA','LAC','TOR','MIN','WAS','CLE','PHX','ATL','CLE','TOR','OKC','MIN','NYK','CHI','DEN','LAL','ATL','UTA','ATL','IND','PHI','UTA','ATL','UTA','','SAS'],   // Vancouver Grizzlies = OKC lineage in this game
  '1995': ['GDN','DEN','PHI','WAS','MIN','MEM','TOR','POR','BKN','MIA','MIL','DAL','SAC','BOS','DEN','ATL','CLE','DET','PHX','IND'],   // McAdoo-style trade-day team (Denver ended up with McDyess)
  '1984': ['HOU','POR','CHI','DAL','PHI','WAS','SAS','LAC','SAC','PHI','ATL','CLE','PHX','LAC','DAL','UTA','BKN','IND','POR','DET','MIL','PHI','LAL','BOS'],
  '1979': ['LAL','CHI','NYK','DET','MIL','OKC','OKC','BKN','NYK','DET','BKN','POR','IND','LAL','DET','PHI','HOU','SAC','SAS','UTA','NYK','PHX'],
};

function runDraftLottery(teams, eraId) {
  const realTeams = REAL_DRAFT_TEAMS[eraId] || [];
  const realSet   = new Set(realTeams.filter(Boolean));

  // Everyone NOT locked into a real historical slot gets simulated normally,
  // sorted by this save's actual standings.
  const sorted = [...teams].filter(t=>!realSet.has(t.id)).sort((a,b) => a.wins - b.wins || b.losses - a.losses);
  const lotteryPool  = sorted.slice(0, Math.max(0, 8-realTeams.length));
  const nonLottery   = sorted.slice(Math.max(0, 8-realTeams.length));

  const assigned = [];
  const pool     = [...lotteryPool];
  const lotterySlotsLeft = Math.max(0, 4 - realTeams.filter((t,i)=>i<4 && t).length);
  for (let i=0; i<lotterySlotsLeft && pool.length>0; i++) {
    const weights = pool.map((_,idx) => pool.length - idx);
    const total   = weights.reduce((s,w)=>s+w,0);
    let rnd       = Math.random()*total;
    let wi        = 0;
    for (let j=0; j<weights.length; j++) { rnd -= weights[j]; if (rnd<=0){wi=j;break;} }
    assigned.push(pool[wi].id);
    pool.splice(wi,1);
  }

  const assignedSet  = new Set(assigned);
  const lotteryRest  = lotteryPool.filter(t=>!assignedSet.has(t.id)).map(t=>t.id);
  const simulatedOrder = [...assigned, ...lotteryRest, ...nonLottery.map(t=>t.id)];

  // Weave the verified real teams into their exact real slots, filling every
  // other slot from the simulated order in sequence — so a real team gets its
  // real pick regardless of how it happened to finish in this save, and every
  // other team still gets a normal, standings-based simulated pick.
  const round1 = [];
  let simIdx = 0;
  for (let i=0; i<30; i++) {
    if (realTeams[i]) {
      round1.push(realTeams[i]);
    } else {
      round1.push(simulatedOrder[simIdx]);
      simIdx++;
    }
  }
  const order = [...round1, ...round1];

  const revealPool = teams.filter(t => realSet.has(t.id) || lotteryPool.some(lt=>lt.id===t.id));
  const reveal = revealPool.map((t) => {
    const seed = realSet.has(t.id) ? realTeams.indexOf(t.id)+1 : lotteryPool.findIndex(lt=>lt.id===t.id)+1;
    const finalPick = round1.indexOf(t.id) + 1;
    return { teamId:t.id, seed, finalPick, movedUp: finalPick < seed, movedDown: finalPick > seed };
  }).sort((a,b) => a.finalPick - b.finalPick);

  return { order, reveal };
}

function cpuPick(available) {
  if (!available.length) return null;
  const sorted  = [...available].sort((a,b) => b.overall - a.overall);
  const rnd     = Math.random();
  if (rnd < 0.72) {
    // Best available — small variance among top 3
    return pick(sorted.slice(0, Math.min(3, sorted.length)));
  } else if (rnd < 0.88) {
    // Reach for high potential (project)
    const proj = [...available].filter(p=>p.potential-p.overall>=18).sort((a,b)=>b.potential-a.potential);
    return proj.length ? proj[0] : sorted[0];
  } else {
    // Positional need (random position)
    const neededPos = pick(POSITIONS);
    const byPos = available.filter(p=>p.pos===neededPos).sort((a,b)=>b.overall-a.overall);
    return byPos.length ? byPos[0] : sorted[0];
  }
}

function gradeDraftClass(results, myTeamId) {
  const myPicks = results.filter(r => r.teamId === myTeamId);
  if (!myPicks.length) return {g:'—',c:'#6B7280'};
  const avgPot = myPicks.reduce((s,r)=>s+r.player.potential,0) / myPicks.length;
  if (avgPot>=88) return {g:'A+',c:'#10B981'};
  if (avgPot>=82) return {g:'A', c:'#10B981'};
  if (avgPot>=76) return {g:'B+',c:'#84CC16'};
  if (avgPot>=70) return {g:'B', c:'#EAB308'};
  if (avgPot>=64) return {g:'C+',c:'#F97316'};
  return {g:'C',c:'#EF4444'};
}

// ===================== COACHING & MANAGEMENT =====================

const COACH_STYLES = [
  { id:'offensive', label:'Offensive System',  desc:'Push the pace. Your scoring output gets a +10% boost.',      ptsBonus:0.10, winBonus:0    },
  { id:'defensive', label:'Defensive Minded',  desc:'Grit and stops. +7% win probability on every game.',         ptsBonus:0,    winBonus:0.07 },
  { id:'balanced',  label:'Balanced',          desc:'No weaknesses. Small bonuses across scoring and winning.',    ptsBonus:0.04, winBonus:0.03 },
  { id:'developer', label:'Player Developer',  desc:'Young players (< 25) improve significantly faster.',         ptsBonus:0,    winBonus:0    },
  { id:'hardnosed', label:'Hard-Nosed',        desc:'Defense and toughness. Teams punch above their weight class.',ptsBonus:0,    winBonus:0.09 },
];

const GM_STYLES = [
  { id:'builder',  label:'Long-Term Builder', desc:'Patience and picks. Draft classes improve by 1 tier.' },
  { id:'winnow',   label:'Win Now',           desc:'Aggressive trades and big FA signings. Cap may suffer.' },
  { id:'balanced', label:'Balanced',          desc:'Steady hand. No flashy moves but no disasters either.' },
];

function genCoach(baseRtg=75, era) {
  const useEra = era || CURRENT_ERA;
  const cap = getSalaryCap(useEra);
  const minSal = getMinSalary(useEra);
  const step = cap < 20 ? 0.01 : 0.5;
  const style = pick(COACH_STYLES);
  const sal = Math.max(minSal, Math.round(rf(cap*0.0107, cap*0.057)/step)*step);
  return { id:Math.random().toString(36).slice(2), name:rname(), style, rating:clamp(baseRtg+ri(-14,14),50,97), contract:{salary:sal, years:ri(2,5)} };
}

function genGM(baseRtg=75, era) {
  const useEra = era || CURRENT_ERA;
  const cap = getSalaryCap(useEra);
  const minSal = getMinSalary(useEra);
  const step = cap < 20 ? 0.01 : 0.5;
  const style = pick(GM_STYLES);
  const sal = Math.max(minSal, Math.round(rf(cap*0.0071, cap*0.043)/step)*step);
  return { id:Math.random().toString(36).slice(2), name:rname(), style, rating:clamp(baseRtg+ri(-12,12),52,96), contract:{salary:sal, years:ri(2,4)} };
}

function initCoaches(teams, era) { const r={}; teams.forEach(t=>{r[t.id]=genCoach(t.rtg, era);}); return r; }
function initGMs(teams, era)     { const r={}; teams.forEach(t=>{r[t.id]=genGM(t.rtg, era);}); return r; }

// SP cost to +1 any attribute — scales with current value
function spCost(val) {
  if (val >= 90) return 55;
  if (val >= 80) return 42;
  if (val >= 70) return 32;
  if (val >= 60) return 24;
  return 16;
}

// SP earned from a game based on performance grade
function spFromGrade(g) {
  return {A:14,B:8,C:3}[g[0]] ?? 2; // A/A+ → 14, B/B+ → 8, C/C+ → 3
}

// ===================== SIMCAST ENGINE =====================

// Possession-by-possession game presentation. Unlike the old version, this
// does NOT generate its own separate flavor-only score — it computes the
// real, calibrated result FIRST (same simGamePair/simPGame the engine uses
// whether you watch or not), then dramatizes that exact outcome one
// possession at a time. Watching a game and auto-simming it now always
// produce the same final score and the same box score — previously the
// live running score during "Watch" had zero connection to what actually
// got recorded afterward, and the recorded stats skipped the shot-log
// system entirely (no FG/3PT/FT splits from watched games).
function buildSimcast(myPlayer, myTeam, oppTeam, baseYear, hasThreePointLine, home=true) {
  const myLast  = myPlayer?.name?.split(' ').pop() || 'Player';
  const roster  = myTeam?.roster || [];
  const oppRoster = oppTeam?.roster || [];
  const starters = [...roster].filter(p=>p.id!==myPlayer?.id).sort((a,b)=>b.overall-a.overall).slice(0,4);
  const oppStars  = [...oppRoster].sort((a,b)=>b.overall-a.overall).slice(0,5);
  const fallbackNames = ['Johnson','Williams','Davis','Brown','Jones'];
  const op  = () => (oppStars.length ? pick(oppStars).name.split(' ').pop() : pick(fallbackNames));
  const tm  = () => (starters.length ? pick(starters).name.split(' ').pop() : pick(fallbackNames));

  // -- The real, calibrated result, computed once, dramatized below --
  const [finalMy, finalOpp] = simGamePair(myTeam.rtg, oppTeam.rtg, home, baseYear);
  const myBox = simPGame(myPlayer, myTeam.rtg, oppTeam.rtg, home, hasThreePointLine);

  const teammateProfile = hasThreePointLine ? SHOT_TYPES_3PT : SHOT_TYPES_PRE3PT;
  let teamRemaining = Math.max(0, finalMy - myBox.pts);
  const teammateEvents = [];
  while (teamRemaining > 0) {
    const s = pickShotType(teammateProfile);
    const isThree = s.type === 'Three-Pointer';
    const pts = isThree ? 3 : 2;
    if (pts > teamRemaining && teamRemaining >= 2) {
      teammateEvents.push({ made:true, pts:2, isThree:false, who:'team' });
      teamRemaining -= 2;
    } else if (teamRemaining === 1) {
      teammateEvents.push({ made:true, pts:1, isThree:false, who:'team', isFT:true });
      teamRemaining -= 1;
    } else {
      teammateEvents.push({ made:true, pts, isThree, who:'team' });
      teamRemaining -= pts;
    }
  }
  let oppRemaining = finalOpp;
  const oppEvents = [];
  while (oppRemaining > 0) {
    const s = pickShotType(teammateProfile);
    const isThree = s.type === 'Three-Pointer';
    const pts = isThree ? 3 : 2;
    if (pts > oppRemaining && oppRemaining >= 2) {
      oppEvents.push({ who:'opp', pts:2, isThree:false });
      oppRemaining -= 2;
    } else if (oppRemaining === 1) {
      oppEvents.push({ who:'opp', pts:1, isThree:false, isFT:true });
      oppRemaining -= 1;
    } else {
      oppEvents.push({ who:'opp', pts, isThree });
      oppRemaining -= pts;
    }
  }

  const myEvents = seededShuffle(myBox.shots.map(s=>({...s, who:'me'})), Math.floor(Math.random()*99999));
  const filler = Array.from({length: ri(6,12)}, () => ({ who:'filler' }));

  const myTeamPossessions = seededShuffle([...myEvents, ...teammateEvents, ...filler], Math.floor(Math.random()*99999));
  const oppPossessions    = seededShuffle([...oppEvents, ...Array.from({length: ri(6,12)}, () => ({who:'oppFiller'}))], Math.floor(Math.random()*99999));

  const combined = [];
  const maxLen = Math.max(myTeamPossessions.length, oppPossessions.length);
  for (let i=0; i<maxLen; i++) {
    if (myTeamPossessions[i]) combined.push(myTeamPossessions[i]);
    if (oppPossessions[i]) combined.push(oppPossessions[i]);
  }

  let rebLeft = myBox.reb, astLeft = myBox.ast, stlLeft = myBox.stl;
  let myScore=0, oppScore=0, myPts=0, myReb=0, myAst=0, myStl=0;
  const plays = [];
  const perQ = Math.max(1, Math.ceil(combined.length/4));

  combined.forEach((ev, idx) => {
    const q = Math.min(4, Math.floor(idx/perQ)+1);
    const diff = myScore - oppScore;
    const isClutch = q===4 && Math.abs(diff)<=5;
    const urgency = isClutch ? ' HUGE PLAY.' : '';
    let text, clr, isScore=false;

    if (ev.who === 'me') {
      if (ev.made) {
        myScore += ev.pts; myPts += ev.pts; isScore = true;
        const shotDesc = ev.type==='Dunk' ? 'throws it down' : ev.type==='Three-Pointer' ? `buries a three from ${ev.dist}ft`
          : ev.type==='Free Throw' ? 'hits the free throw' : `hits a ${ev.type.toLowerCase()} from ${ev.dist}ft`;
        text = `${myLast} ${shotDesc}.${urgency}`;
        clr = ACC;
      } else {
        text = `${myLast} ${ev.type==='Free Throw'?'misses the free throw':`misses the ${ev.type.toLowerCase()}`}. ${op()} with the rebound.`;
        clr = MUTED;
      }
    } else if (ev.who === 'team') {
      myScore += ev.pts; isScore = true;
      if (astLeft>0 && Math.random()<0.5) { astLeft--; myAst++; }
      text = ev.isFT ? `${tm()} hits from the line.`
        : `${myLast} finds ${tm()} ${pick(['cutting to the rim','wide open in the corner','rolling hard to the basket'])} -- bucket!`;
      clr = '#3B82F6';
    } else if (ev.who === 'opp') {
      oppScore += ev.pts; isScore = true;
      text = ev.isThree ? `${op()} from downtown -- THREE.${Math.abs(diff)<=2?' TIED GAME!':''}`
        : `${op()} scores inside.${diff<0?` ${oppTeam.name} extend.`:''}`;
      clr = LOSS;
    } else if (ev.who === 'filler') {
      if (rebLeft>0 && Math.random()<0.35) { rebLeft--; myReb++; text = `${op()} misses. ${myLast} with the rebound.`; clr='#8B5CF6'; }
      else if (stlLeft>0 && Math.random()<0.3) { stlLeft--; myStl++; text = `${myLast} reads the pass -- STEAL!`; clr=WIN; }
      else { text = `${pick([tm(),myLast])} can't connect. ${op()} recovers.`; clr = MUTED; }
    } else {
      text = `${op()} defense forces a tough possession.`; clr = MUTED;
    }

    myScore = Math.min(myScore, finalMy); oppScore = Math.min(oppScore, finalOpp);
    plays.push({ id:plays.length, q, text, clr, myScore, oppScore, myPts, myReb, myAst, myStl, isScore });
    if (idx>0 && (idx+1)%perQ===0 && q<4) {
      plays.push({ id:plays.length, q, isQEnd:true, text:`-- End of Q${q} -- ${myTeam.name} ${myScore}, ${oppTeam.name} ${oppScore} --`,
        myScore, oppScore, myPts, myReb, myAst, myStl });
    }
  });

  const won = finalMy > finalOpp;
  plays.push({ id:plays.length, q:4, isQEnd:true, text:`-- FINAL -- ${myTeam.name} ${finalMy}, ${oppTeam.name} ${finalOpp} --`,
    myScore:finalMy, oppScore:finalOpp, myPts:myBox.pts, myReb:myBox.reb, myAst:myBox.ast, myStl:myBox.stl });

  const finalPStats = { pts:myBox.pts, reb:myBox.reb, ast:myBox.ast, stl:myBox.stl, blk:myBox.blk, min:myBox.min,
    fgm:myBox.fgm, fga:myBox.fga, tpm:myBox.tpm, tpa:myBox.tpa, ftm:myBox.ftm, fta:myBox.fta, shots:myBox.shots };

  return { plays, won, finalMyScore:finalMy, finalOppScore:finalOpp, finalPStats, oppId:oppTeam.id, myTeamId:myTeam.id };
}

// News item generator — templated, based on game/season context
function makeNews(won, pStats, sSt, myPlayer, myTeam) {
  const g    = Math.max(1, sSt.games);
  const ppg  = fmt(sSt.pts/g), apg = fmt(sSt.ast/g);
  const news = [];
  const wPct = Math.round(sSt.wins/(Math.max(1,sSt.wins+sSt.losses))*100);

  if (won  && sSt.wins>0  && sSt.wins%5===0)  news.push(`🔥 ${myTeam?.name} have won ${sSt.wins} games this season.`);
  if (!won && sSt.losses>0 && sSt.losses%3===0) news.push(`📉 Rough stretch — ${myTeam?.name} have dropped ${sSt.losses} this year.`);
  if (pStats.pts>=30) news.push(`⭐ ${myPlayer?.name} erupts for ${pStats.pts} in ${won?'the win':'the loss'}. League taking notice.`);
  if (pStats.ast>=10) news.push(`🎯 ${pStats.ast}-assist night for ${myPlayer?.name?.split(' ')[0]}. Playmaking at an elite level.`);
  if (ppg>=25)        news.push(`📊 ${myPlayer?.name} averaging ${ppg} PPG — top-5 in the league at this pace.`);
  if (apg>=8)         news.push(`📊 ${apg} APG this season puts ${myPlayer?.name?.split(' ')[0]} among the best distributors in the game.`);
  if (wPct>=60)       news.push(`📈 ${myTeam?.name} sitting at ${sSt.wins}-${sSt.losses}. Playoff picture looking strong.`);
  if (wPct<35&&g>10)  news.push(`👀 Trade deadline approaching. ${myTeam?.name} at ${sSt.wins}-${sSt.losses} could be sellers.`);
  if (!news.length)   news.push(`📋 ${myPlayer?.name?.split(' ')[0]} posted ${pStats.pts}/${pStats.reb}/${pStats.ast} in ${won?'the W':'the L'}.`);

  return news.slice(0,2);
}

// Hot/cold streak from recent grades
function getStreak(grades) {
  if (grades.length < 3) return null;
  const last3 = grades.slice(-3);
  const hot  = last3.every(g => g==='A+' || g==='A' || g==='B+');
  const cold = last3.every(g => g==='C'  || g==='C+');
  if (hot)  return { type:'hot',  label:'🔥 Hot Streak', clr:'#EA580C', bg:'#FEF3C7', desc:'+10% boost next sim' };
  if (cold) return { type:'cold', label:'🧊 Cold Streak', clr:'#3B82F6', bg:'#EFF6FF', desc:'Focus: play the next game' };
  return null;
}

// ===================== GM TRADE VALUE =====================

function expectedSalary(ovr, era, name) {
  // Was previously a separate, hardcoded, non-era-scaled, non-accolades-aware
  // formula (flat $16M for any OVR 80 player, in any year) - meant real
  // accolades-priced stars got falsely flagged as "overpaid" against a market
  // baseline that had no idea who they were. Reuses calcSalary directly so
  // the "market" comparison always matches what the player is actually
  // correctly worth.
  return calcSalary(ovr, era, name);
}

function tradeValue(p) {
  const base   = p.overall * 2;
  const pot    = Math.max(0,(p.potential-p.overall)*0.6);
  const young  = Math.max(0,(28-p.age)*1.8);
  const old    = Math.max(0,(p.age-31)*2.5);
  const overpd = Math.max(0,(p.contract.salary-expectedSalary(p.overall, null, p.name))*0.8);
  let v = Math.max(0, base+pot+young-old-overpd);
  // Star premium - elite players are worth dramatically more than the sum
  // of several good-but-not-great players, not just moderately more (was
  // flat 1.15x/1.3x, which let e.g. two solid role players' combined value
  // outweigh a true top-5 superstar - not how real trade value works).
  if (p.overall>=93) v*=2.4;
  else if (p.overall>=90) v*=1.9;
  else if (p.overall>=87) v*=1.55;
  else if (p.overall>=83) v*=1.25;
  return Math.round(v);
}

// Trade Block finder — scans the rest of the league for players who fill
// your team's biggest need, and packages a fair (tradeValue-balanced) offer
// using your own most expendable pieces (bench players outside your top
// rotation). Returns up to 4 ranked suggestions.
function findTradeSuggestions(myTeam, teams) {
  if (!myTeam?.roster?.length) return [];
  const myNeed = teamNeed(myTeam);
  const mySorted = [...myTeam.roster].sort((a,b)=>b.overall-a.overall);
  const myExpendable = mySorted.slice(Math.min(3, mySorted.length)); // bench pieces you'd realistically move

  const candidates = [];
  teams.filter(t=>t.id!==myTeam.id).forEach(theirT => {
    (theirT.roster||[]).forEach(p => {
      if ((p.attrs?.[myNeed]||0) < 78) return; // only real upgrades at the position of need
      candidates.push({ player: p, team: theirT });
    });
  });
  candidates.sort((a,b)=>(b.player.attrs?.[myNeed]||0) - (a.player.attrs?.[myNeed]||0));

  const suggestions = [];
  const usedPlayerIds = new Set();
  for (const { player: target, team: theirT } of candidates) {
    if (suggestions.length >= 4) break;
    if (usedPlayerIds.has(target.id)) continue;
    const targetVal = tradeValue(target);
    // find the smallest combo of your expendable players whose value is close to targetVal
    let bestCombo = null, bestDiff = Infinity;
    for (const p1 of myExpendable) {
      const v1 = tradeValue(p1);
      const diff1 = Math.abs(v1 - targetVal);
      if (diff1 < bestDiff && v1/Math.max(1,targetVal) <= 1.35) { bestCombo=[p1]; bestDiff=diff1; }
      for (const p2 of myExpendable) {
        if (p2.id===p1.id) continue;
        const v2 = v1 + tradeValue(p2);
        const diff2 = Math.abs(v2 - targetVal);
        if (diff2 < bestDiff && v2/Math.max(1,targetVal) <= 1.35 && v2/Math.max(1,targetVal) >= 0.7) { bestCombo=[p1,p2]; bestDiff=diff2; }
      }
    }
    if (!bestCombo) continue;
    const comboVal = bestCombo.reduce((s,p)=>s+tradeValue(p),0);
    const fairness = comboVal/Math.max(1,targetVal);
    if (fairness < 0.65 || fairness > 1.5) continue;
    usedPlayerIds.add(target.id);
    suggestions.push({
      theirTeam: theirT, targetPlayer: target, give: bestCombo,
      fairness, needAddressed: myNeed,
    });
  }
  return suggestions;
}

// ===================== SATISFACTION SYSTEM =====================

function satLabel(sat) {
  if (sat >= 75) return { text:'Happy',    clr:WIN,       bg:'#D1FAE5', icon:'😊' };
  if (sat >= 50) return { text:'Content',  clr:'#D97706', bg:'#FEF3C7', icon:'😐' };
  if (sat >= 30) return { text:'Restless', clr:'#EA580C', bg:'#FFEDD5', icon:'😕' };
  return              { text:'Wants Out',  clr:LOSS,      bg:'#FEE2E2', icon:'😤' };
}

// Run at end of each simulated season — updates satisfaction for every player
function updateSatisfaction(teams, satBonus=0) {
  return teams.map(team => {
    const wPct     = (team.wins+team.losses)>0 ? team.wins/(team.wins+team.losses) : 0.5;
    const playoffs = team.wins >= 38;
    const sorted   = [...team.roster].sort((a,b)=>b.overall-a.overall);
    const newRoster = sorted.map((p, idx) => {
      let d = satBonus; // difficulty modifier applied to every player
      // Win/loss
      if (wPct >= 0.60) d += 14; else if (wPct >= 0.45) d += 4;
      else if (wPct < 0.35) d -= 14; else if (wPct < 0.25) d -= 22;
      // Role
      if (idx === 0) d += 10;           // franchise player — team's built around me
      else if (idx <= 4) d += 0;        // starter
      else if (idx <= 8) d -= 6;        // rotation
      else d -= 12;                     // deep bench
      // Salary vs market
      const market  = expectedSalary(p.overall, null, p.name);
      const salDiff = p.contract.salary - market;
      if (salDiff >= 6) d += 10;        // well paid
      else if (salDiff <= -6) d -= 18;  // underpaid — simmering
      // Playoff bonus
      if (playoffs) d += 8;
      // Veterans hate losing more
      if (p.age >= 30 && wPct < 0.45) d -= 6;
      // Noise
      d += ri(-6, 6);
      return { ...p, satisfaction: clamp((p.satisfaction??70)+d, 0, 100) };
    });
    return { ...team, roster: newRoster };
  });
}

// Determine whether each expiring player re-signs — returns {stayed, left} arrays per team
function resolveContracts(teams) {
  return teams.map(team => {
    const stayed = [], left = [];
    team.roster.forEach(p => {
      const newYears = p.contract.years - 1;
      if (newYears > 0) {
        stayed.push({ ...p, contract:{ ...p.contract, years:newYears } });
      } else {
        // Contract expired — re-sign probability based on satisfaction
        const sat  = p.satisfaction ?? 70;
        const prob = sat>=75?0.84 : sat>=55?0.58 : sat>=35?0.28 : 0.08;
        if (Math.random() < prob) {
          const discount = sat >= 70 ? 0.93 : 1.0; // happy players take slight hometown discount
          const newSal   = Math.round(calcSalary(p.overall)*discount*2)/2;
          stayed.push({ ...p, contract:{ salary:newSal, years:ri(2,4) } });
        } else {
          left.push(p); // walks in free agency
        }
      }
    });
    return { ...team, roster:stayed, _playersLeft:left };
  });
}

