// Derives the current point in the season from existing game state —
// no new state needed, just reads what's already tracked.
function getSeasonPhase({ gamesPlayed, gIdx, scheduleLen, playoffs }) {
  if (playoffs && !playoffs.champion && !playoffs.missed) return 'playoffs';
  if (playoffs && (playoffs.champion || playoffs.missed))  return 'offseason';
  if (gamesPlayed === 0 && gIdx === 0)                      return 'preseason';
  if (scheduleLen && gIdx >= scheduleLen)                   return 'offseason';
  return 'regular';
}

