// ── Bottom Navigation Bar ──────────────────────────────────────────
const BottomNav = ({screen, go, mode, teamClr=ACC, extraItems=[]}) => {
  // Mobile browsers (especially iOS Safari) can report window.innerHeight
  // larger than what's actually visible on screen when browser chrome
  // (address bar) is showing - position:fixed;bottom:0 then anchors below
  // the true visible viewport, making the nav unreachable. Correct for the
  // gap directly using the Visual Viewport API, which always reflects what's
  // actually on screen.
  const [bottomOffset, setBottomOffset] = useState(0);
  useEffect(() => {
    if (!window.visualViewport) return;
    const update = () => {
      const vv = window.visualViewport;
      const gap = window.innerHeight - (vv.height + vv.offsetTop);
      setBottomOffset(Math.max(0, gap));
    };
    update();
    window.visualViewport.addEventListener('resize', update);
    window.visualViewport.addEventListener('scroll', update);
    return () => {
      window.visualViewport.removeEventListener('resize', update);
      window.visualViewport.removeEventListener('scroll', update);
    };
  }, []);
  const careerItems = [
    {icon:'⚡', label:'Hub',      dest:'careerHub'},
    {icon:'📅', label:'Schedule', dest:'schedule'},
    {icon:'🏠', label:'Home',     dest:'dashboard'},
    {icon:'👥', label:'Roster',   dest:'roster'},
    {icon:'📊', label:'League',   dest:'standings'},
  ];
  const gmItems = [
    {icon:'🏠', label:'Overview', dest:'gmDashboard'},
    {icon:'📅', label:'Calendar', dest:'gmCalendar'},
    {icon:'👥', label:'Roster',   dest:'roster'},
    {icon:'🔄', label:'Trades',   dest:'gmTradePick'},
    {icon:'📊', label:'League',   dest:'standings'},
    {icon:'🎯', label:'Scout',    dest:'scoutingRoom'},
    {icon:'⋯',  label:'More',     dest:'gmMore'},
  ];
  const items = [...(mode==='career' ? careerItems : gmItems), ...extraItems];
  const activeClr = teamClr;
  return (
    <div style={{position:'fixed',bottom:bottomOffset,left:0,right:0,zIndex:50,background:'rgba(255,255,255,0.97)',backdropFilter:'blur(24px)',WebkitBackdropFilter:'blur(24px)',borderTop:`1px solid ${BORD}`,display:'flex',alignItems:'stretch',paddingBottom:'env(safe-area-inset-bottom)'}}>
      {items.map(({icon,label,dest})=>{
        const active = screen===dest;
        return (
          <button key={dest} onClick={()=>go(dest)}
            style={{flex:1,display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',gap:'3px',border:'none',background:'transparent',cursor:'pointer',padding:'8px 4px 10px',fontFamily:"'Karla',system-ui,sans-serif",WebkitTapHighlightColor:'transparent'}}>
            <span style={{fontSize:'20px',lineHeight:1,filter:active?'none':'grayscale(0.3) opacity(0.55)'}}>{icon}</span>
            <span style={{fontSize:'10px',fontWeight:active?700:500,color:active?activeClr:MUTED,letterSpacing:'0.2px'}}>{label}</span>
            {active && <div style={{position:'absolute',bottom:0,width:'28px',height:'3px',background:activeClr,borderRadius:'3px 3px 0 0'}}/>}
          </button>
        );
      })}
    </div>
  );
};

