  const [coachGoal, setCoachGoal]       = useState(null);   // {stat,target,bonus,desc,met,oppId}
  const [careerCoach, setCareerCoach]   = useState(null);   // {name, isReal} - the team's real head coach when known
  const [careerTotals, setCareerTotals] = useState({pts:0,reb:0,ast:0,stl:0,blk:0,wins:0,games:0,seasons:0,tripleDoubles:0,allStars:0,rings:0});
  const [unlockedAchs, setUnlockedAchs]   = useState([]);   // array of achievement IDs
  const [achTab,       setAchTab]         = useState('All');
  const [ovrHistory,   setOvrHistory]     = useState([]);   // [{season, ovr}] for bio chart
  const [milestones, setMilestones]     = useState([]);     // achieved milestone strings
  const [endorsement, setEndorsement]   = useState(null);   // {brand,tier,bonus}
  const [socialFeed, setSocialFeed]     = useState([]);     // [{handle,text}]
  const [pressConf, setPressConf]       = useState(null);   // {q,choices} post-game press
  const [showHomeMenu, setShowHomeMenu] = useState(false);  // save/quit modal
  const [showDrawer, setShowDrawer] = useState(false);      // hamburger drawer
  // ── MyCareer narrative ──────────────────────────────────────────────
