          fontFamily:DISP,
          letterSpacing:'-3px',
          lineHeight:1,
          color:'#1C1008',
          /* layered shadows give depth + slight 3D lift like the logo */
          textShadow:'1px 1px 0 #3D1E08, 2px 2px 0 #4A2810, 3px 3px 0 rgba(0,0,0,0.18), 0 6px 24px rgba(100,50,10,0.10)',
